class AllocContext
{
    public nint Ptr;    // alloc_ptr: start of free space
    public nint Limit;  // alloc_limit: end of the chunk

    public nint TryAlloc(int size)
    {
        nint end = Ptr + size;
        if (end > Limit) return 0;  // does not fit: slow path
        nint obj = Ptr;
        Ptr = end;                  // the entire "search for room"
        return obj;
    }
}
